-- PREPARED ONLY; target Selcore ffznkypurnocabqyxpps. Never run on iVenue.
-- Administrative database connection required. No schema or policy changes.
BEGIN;
LOCK TABLE public.categories, public.brands, public.products IN SHARE ROW EXCLUSIVE MODE;
DO $seed$
DECLARE
  item jsonb; expected jsonb; existing public.products%ROWTYPE;
  category_key bigint; brand_key bigint; existing_slug text;
  inserted_categories integer := 0; inserted_brands integer := 0; inserted_products integer := 0;
  affected integer; sequence_name text; sequence_last bigint; maximum_id bigint;
BEGIN
  FOR item IN SELECT value FROM jsonb_array_elements('[{"name":"accessory","slug":"accessory"},{"name":"laptop","slug":"laptop"},{"name":"mobile","slug":"mobile"},{"name":"tablet","slug":"tablet"}]'::jsonb) LOOP
    IF EXISTS (SELECT 1 FROM public.categories WHERE (name = item->>'name' OR slug = item->>'slug')
      AND (name IS DISTINCT FROM item->>'name' OR slug IS DISTINCT FROM item->>'slug')) THEN
      RAISE EXCEPTION 'Category conflict: %', item->>'name';
    END IF;
    INSERT INTO public.categories(name, slug) VALUES (item->>'name', item->>'slug') ON CONFLICT DO NOTHING;
    GET DIAGNOSTICS affected = ROW_COUNT; inserted_categories := inserted_categories + affected;
  END LOOP;
  FOR item IN SELECT value FROM jsonb_array_elements('[{"name":"ASUS","slug":"asus"},{"name":"Acer","slug":"acer"},{"name":"Apple","slug":"apple"},{"name":"Dell","slug":"dell"},{"name":"Google","slug":"google"},{"name":"HP","slug":"hp"},{"name":"Huawei","slug":"huawei"},{"name":"JBL","slug":"jbl"},{"name":"Lenovo","slug":"lenovo"},{"name":"Logitech","slug":"logitech"},{"name":"Microsoft","slug":"microsoft"},{"name":"Nothing","slug":"nothing"},{"name":"OnePlus","slug":"oneplus"},{"name":"Razer","slug":"razer"},{"name":"Samsung","slug":"samsung"},{"name":"Sony","slug":"sony"},{"name":"Xiaomi","slug":"xiaomi"}]'::jsonb) LOOP
    IF EXISTS (SELECT 1 FROM public.brands WHERE (name = item->>'name' OR slug = item->>'slug')
      AND (name IS DISTINCT FROM item->>'name' OR slug IS DISTINCT FROM item->>'slug')) THEN
      RAISE EXCEPTION 'Brand conflict: %', item->>'name';
    END IF;
    INSERT INTO public.brands(name, slug) VALUES (item->>'name', item->>'slug') ON CONFLICT DO NOTHING;
    GET DIAGNOSTICS affected = ROW_COUNT; inserted_brands := inserted_brands + affected;
  END LOOP;
  FOR item IN SELECT value FROM jsonb_array_elements('[{"id":1,"category_name":"mobile","brand_name":"Apple","name":"iPhone 15 Pro","slug":"iphone-15-pro-1","description":"","price":2999,"sale_price":2699,"currency":"GEL","specifications":{"brand":"Apple","storage":"256GB","ram":"8GB","display":"6.1 inch OLED","camera":"48MP"},"stock_quantity":0,"is_active":true,"is_purchasable":false,"is_bestseller":true,"is_new_arrival":false},{"id":2,"category_name":"mobile","brand_name":"Samsung","name":"Samsung Galaxy S24 Ultra","slug":"samsung-galaxy-s24-ultra-2","description":"","price":3499,"sale_price":null,"currency":"GEL","specifications":{"brand":"Samsung","storage":"512GB","ram":"12GB","display":"6.8 inch AMOLED","camera":"200MP"},"stock_quantity":0,"is_active":true,"is_purchasable":false,"is_bestseller":true,"is_new_arrival":false},{"id":3,"category_name":"mobile","brand_name":"Google","name":"Google Pixel 8","slug":"google-pixel-8-3","description":"","price":1899,"sale_price":1599,"currency":"GEL","specifications":{"brand":"Google","storage":"128GB","ram":"8GB","display":"6.2 inch OLED","camera":"50MP"},"stock_quantity":0,"is_active":true,"is_purchasable":false,"is_bestseller":false,"is_new_arrival":true},{"id":4,"category_name":"laptop","brand_name":"Apple","name":"MacBook Air M3","slug":"macbook-air-m3-4","description":"","price":3999,"sale_price":null,"currency":"GEL","specifications":{"brand":"Apple","processor":"Apple M3","ram":"16GB","storage":"512GB SSD","screen":"13.6 inch Retina"},"stock_quantity":0,"is_active":true,"is_purchasable":false,"is_bestseller":true,"is_new_arrival":false},{"id":5,"category_name":"laptop","brand_name":"Lenovo","name":"Lenovo Legion 5","slug":"lenovo-legion-5-5","description":"","price":3299,"sale_price":2899,"currency":"GEL","specifications":{"brand":"Lenovo","processor":"AMD Ryzen 7","ram":"16GB","storage":"1TB SSD","gpu":"RTX 4060"},"stock_quantity":0,"is_active":true,"is_purchasable":false,"is_bestseller":false,"is_new_arrival":false},{"id":6,"category_name":"laptop","brand_name":"ASUS","name":"ASUS ROG Strix G16","slug":"asus-rog-strix-g16-6","description":"","price":4599,"sale_price":null,"currency":"GEL","specifications":{"brand":"ASUS","processor":"Intel Core i9","ram":"32GB","storage":"1TB SSD","gpu":"RTX 4070"},"stock_quantity":0,"is_active":true,"is_purchasable":false,"is_bestseller":true,"is_new_arrival":false},{"id":7,"category_name":"tablet","brand_name":"Apple","name":"iPad Pro M4","slug":"ipad-pro-m4-7","description":"","price":3199,"sale_price":2899,"currency":"GEL","specifications":{"brand":"Apple","chip":"M4","storage":"256GB","display":"11 inch OLED","battery":"10 hours"},"stock_quantity":0,"is_active":true,"is_purchasable":false,"is_bestseller":true,"is_new_arrival":false},{"id":8,"category_name":"tablet","brand_name":"Samsung","name":"Samsung Galaxy Tab S9","slug":"samsung-galaxy-tab-s9-8","description":"","price":2499,"sale_price":null,"currency":"GEL","specifications":{"brand":"Samsung","storage":"256GB","ram":"12GB","display":"11 inch AMOLED","penSupport":true},"stock_quantity":0,"is_active":true,"is_purchasable":false,"is_bestseller":false,"is_new_arrival":false},{"id":9,"category_name":"accessory","brand_name":"Apple","name":"AirPods Pro 2","slug":"airpods-pro-2-9","description":"","price":899,"sale_price":749,"currency":"GEL","specifications":{"brand":"Apple","type":"Wireless Earbuds","battery":"6 hours","noiseCanceling":true,"connection":"Bluetooth 5.3"},"stock_quantity":0,"is_active":true,"is_purchasable":false,"is_bestseller":true,"is_new_arrival":false},{"id":10,"category_name":"accessory","brand_name":"Logitech","name":"Logitech MX Master 3S","slug":"logitech-mx-master-3s-10","description":"","price":399,"sale_price":null,"currency":"GEL","specifications":{"brand":"Logitech","type":"Wireless Mouse","dpi":"8000 DPI","battery":"70 days","connection":"Bluetooth"},"stock_quantity":0,"is_active":true,"is_purchasable":false,"is_bestseller":true,"is_new_arrival":false},{"id":11,"category_name":"accessory","brand_name":"Samsung","name":"Samsung 45W Fast Charger","slug":"samsung-45w-fast-charger-11","description":"","price":149,"sale_price":99,"currency":"GEL","specifications":{"brand":"Samsung","power":"45W","port":"USB-C","cableIncluded":true},"stock_quantity":0,"is_active":true,"is_purchasable":false,"is_bestseller":false,"is_new_arrival":false},{"id":12,"category_name":"mobile","brand_name":"Xiaomi","name":"Xiaomi 14 Ultra","slug":"xiaomi-14-ultra-12","description":"","price":2799,"sale_price":2399,"currency":"GEL","specifications":{"brand":"Xiaomi","storage":"512GB","ram":"16GB","display":"6.73 inch AMOLED","camera":"50MP Quad Camera"},"stock_quantity":0,"is_active":true,"is_purchasable":false,"is_bestseller":true,"is_new_arrival":false},{"id":13,"category_name":"mobile","brand_name":"OnePlus","name":"OnePlus 12","slug":"oneplus-12-13","description":"","price":2299,"sale_price":null,"currency":"GEL","specifications":{"brand":"OnePlus","storage":"256GB","ram":"12GB","display":"6.82 inch AMOLED","battery":"5400mAh"},"stock_quantity":0,"is_active":true,"is_purchasable":false,"is_bestseller":false,"is_new_arrival":false},{"id":14,"category_name":"mobile","brand_name":"Nothing","name":"Nothing Phone 2","slug":"nothing-phone-2-14","description":"","price":1599,"sale_price":1299,"currency":"GEL","specifications":{"brand":"Nothing","storage":"256GB","ram":"12GB","display":"6.7 inch OLED","design":"Transparent Back"},"stock_quantity":0,"is_active":true,"is_purchasable":false,"is_bestseller":false,"is_new_arrival":true},{"id":15,"category_name":"laptop","brand_name":"Dell","name":"Dell XPS 13 Plus","slug":"dell-xps-13-plus-15","description":"","price":3899,"sale_price":null,"currency":"GEL","specifications":{"brand":"Dell","processor":"Intel Core i7","ram":"16GB","storage":"512GB SSD","screen":"13.4 inch 4K"},"stock_quantity":0,"is_active":true,"is_purchasable":false,"is_bestseller":true,"is_new_arrival":false},{"id":16,"category_name":"laptop","brand_name":"HP","name":"HP Spectre x360","slug":"hp-spectre-x360-16","description":"","price":3599,"sale_price":3199,"currency":"GEL","specifications":{"brand":"HP","processor":"Intel Core Ultra 7","ram":"16GB","storage":"1TB SSD","screen":"OLED Touch"},"stock_quantity":0,"is_active":true,"is_purchasable":false,"is_bestseller":false,"is_new_arrival":false},{"id":17,"category_name":"laptop","brand_name":"Acer","name":"Acer Predator Helios Neo","slug":"acer-predator-helios-neo-17","description":"","price":4199,"sale_price":null,"currency":"GEL","specifications":{"brand":"Acer","processor":"Intel Core i7","ram":"32GB","storage":"1TB SSD","gpu":"RTX 4070"},"stock_quantity":0,"is_active":true,"is_purchasable":false,"is_bestseller":true,"is_new_arrival":false},{"id":18,"category_name":"tablet","brand_name":"Microsoft","name":"Microsoft Surface Pro 10","slug":"microsoft-surface-pro-10-18","description":"","price":2999,"sale_price":null,"currency":"GEL","specifications":{"brand":"Microsoft","processor":"Intel Core Ultra 5","ram":"16GB","storage":"512GB SSD","display":"13 inch PixelSense"},"stock_quantity":0,"is_active":true,"is_purchasable":false,"is_bestseller":false,"is_new_arrival":false},{"id":19,"category_name":"tablet","brand_name":"Lenovo","name":"Lenovo Tab P12","slug":"lenovo-tab-p12-19","description":"","price":1199,"sale_price":999,"currency":"GEL","specifications":{"brand":"Lenovo","storage":"128GB","ram":"8GB","display":"12.7 inch LCD","speakers":"JBL Quad Speakers"},"stock_quantity":0,"is_active":true,"is_purchasable":false,"is_bestseller":false,"is_new_arrival":true},{"id":20,"category_name":"tablet","brand_name":"Huawei","name":"Huawei MatePad 11.5","slug":"huawei-matepad-11-5-20","description":"","price":999,"sale_price":799,"currency":"GEL","specifications":{"brand":"Huawei","storage":"128GB","ram":"6GB","display":"11.5 inch LCD","battery":"7700mAh"},"stock_quantity":0,"is_active":true,"is_purchasable":false,"is_bestseller":false,"is_new_arrival":false},{"id":21,"category_name":"accessory","brand_name":"Sony","name":"Sony WH-1000XM5","slug":"sony-wh-1000xm5-21","description":"","price":1199,"sale_price":null,"currency":"GEL","specifications":{"brand":"Sony","type":"Wireless Headphones","noiseCanceling":true,"battery":"30 hours","connection":"Bluetooth 5.2"},"stock_quantity":0,"is_active":true,"is_purchasable":false,"is_bestseller":true,"is_new_arrival":false},{"id":22,"category_name":"accessory","brand_name":"Razer","name":"Razer BlackWidow V4 Keyboard","slug":"razer-blackwidow-v4-keyboard-22","description":"","price":699,"sale_price":549,"currency":"GEL","specifications":{"brand":"Razer","type":"Gaming Keyboard","switches":"Mechanical","rgb":true,"connection":"USB"},"stock_quantity":0,"is_active":true,"is_purchasable":false,"is_bestseller":false,"is_new_arrival":false},{"id":23,"category_name":"accessory","brand_name":"Apple","name":"Apple Watch Series 9","slug":"apple-watch-series-9-23","description":"","price":1299,"sale_price":null,"currency":"GEL","specifications":{"brand":"Apple","display":"45mm Retina","waterproof":true,"battery":"18 hours","healthSensors":true},"stock_quantity":0,"is_active":true,"is_purchasable":false,"is_bestseller":true,"is_new_arrival":true},{"id":24,"category_name":"accessory","brand_name":"JBL","name":"JBL Charge 5","slug":"jbl-charge-5-24","description":"","price":499,"sale_price":399,"currency":"GEL","specifications":{"brand":"JBL","type":"Bluetooth Speaker","battery":"20 hours","waterproof":true,"power":"40W"},"stock_quantity":0,"is_active":true,"is_purchasable":false,"is_bestseller":true,"is_new_arrival":false}]'::jsonb) LOOP
    SELECT id INTO STRICT category_key FROM public.categories WHERE name = item->>'category_name';
    SELECT id INTO STRICT brand_key FROM public.brands WHERE name = item->>'brand_name';
    expected := (item - 'category_name' - 'brand_name') || jsonb_build_object('category_id', category_key, 'brand_id', brand_key);
    FOR existing IN SELECT * FROM public.products WHERE id = (item->>'id')::bigint OR slug = item->>'slug' LOOP
      IF EXISTS (SELECT 1 FROM jsonb_each(expected) entry WHERE to_jsonb(existing)->entry.key IS DISTINCT FROM entry.value) THEN
        RAISE EXCEPTION 'Product conflict for source ID % (existing ID %)', item->>'id', existing.id;
      END IF;
    END LOOP;
    INSERT INTO public.products(id, category_id, brand_id, name, slug, description, price, sale_price, currency,
      specifications, stock_quantity, is_active, is_purchasable, is_bestseller, is_new_arrival)
    VALUES ((item->>'id')::bigint, category_key, brand_key, item->>'name', item->>'slug', item->>'description',
      (item->>'price')::numeric, (item->>'sale_price')::numeric, item->>'currency', item->'specifications',
      0, true, false, (item->>'is_bestseller')::boolean, (item->>'is_new_arrival')::boolean)
    ON CONFLICT DO NOTHING;
    GET DIAGNOSTICS affected = ROW_COUNT; inserted_products := inserted_products + affected;
  END LOOP;
  IF (SELECT count(*) FROM public.categories) <> 4 OR (SELECT count(*) FROM public.brands) <> 17
     OR (SELECT count(*) FROM public.products) <> 24 THEN
    RAISE EXCEPTION 'Unexpected extra catalogue records; review rather than deleting them';
  END IF;
  -- Explicit IDs do not advance identity sequences. Never move an existing sequence backwards.
  sequence_name := pg_get_serial_sequence('public.products', 'id');
  EXECUTE format('SELECT last_value FROM %s', sequence_name::regclass) INTO sequence_last;
  SELECT max(id) INTO maximum_id FROM public.products;
  IF maximum_id >= sequence_last THEN PERFORM setval(sequence_name::regclass, maximum_id, true); END IF;
  RAISE NOTICE 'Inserted categories %, brands %, products %; skipped categories %, brands %, products %',
    inserted_categories, inserted_brands, inserted_products, 4-inserted_categories, 17-inserted_brands, 24-inserted_products;
END
$seed$;
COMMIT;
